import { getSupabaseClient, isRealSupabaseConfigured } from './supabase.js';
import { probeUrl } from './checker.js';
import { sendAlertNotification } from './notifier.js';
import type { MonitoredSite, MonitorCheck, Incident, AlertChannel } from '@pingwatch/shared';

function formatDuration(ms: number): string {
  const seconds = Math.floor(ms / 1000);
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  if (minutes < 60) return `${minutes}m ${remainingSeconds}s`;
  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return `${hours}h ${remainingMinutes}m`;
}

async function runWorker(): Promise<void> {
  console.log(`[Worker] Run started at ${new Date().toISOString()}`);

  const supabase = getSupabaseClient();
  const isReal = isRealSupabaseConfigured();

  // STEP 1 — Fetch active sites
  let sites: MonitoredSite[] = [];
  if (isReal) {
    const { data, error } = await supabase
      .from('monitored_sites')
      .select('*')
      .eq('is_active', true);

    if (error) {
      console.error('[Worker] Error fetching active sites:', error);
      process.exit(1);
    }
    sites = data || [];
  } else {
    // In local dev/fallback mode without Supabase connection, probe demo endpoints or test targets
    console.log('[Worker] Running in local demo mode (no live Supabase credentials)');
    sites = [
      {
        id: 'site-demo-1',
        user_id: 'usr_demo_123',
        name: 'Stripe Status Page',
        url: 'https://status.stripe.com',
        check_interval_s: 60,
        is_active: true,
        last_status: 'up',
        last_checked_at: null,
        created_at: new Date().toISOString(),
      },
      {
        id: 'site-demo-2',
        user_id: 'usr_demo_123',
        name: 'GitHub Status',
        url: 'https://www.githubstatus.com',
        check_interval_s: 60,
        is_active: true,
        last_status: 'up',
        last_checked_at: null,
        created_at: new Date().toISOString(),
      }
    ];
  }

  console.log(`[Worker] Found ${sites.length} active sites`);

  // STEP 2 — Filter sites due for a check
  const now = Date.now();
  const dueSites = sites.filter((site) => {
    if (!site.last_checked_at) return true;
    const lastCheckedTime = new Date(site.last_checked_at).getTime();
    const elapsedSeconds = (now - lastCheckedTime) / 1000;
    return elapsedSeconds >= site.check_interval_s;
  });

  console.log(`[Worker] ${dueSites.length} sites are due for checking`);

  if (dueSites.length === 0) {
    console.log('[Worker] No sites due. Exiting.');
    process.exit(0);
  }

  // STEP 3 — Probe each due site in parallel
  const probePromises = dueSites.map(async (site) => {
    const result = await probeUrl(site.url);
    return { site, result };
  });

  const settledResults = await Promise.allSettled(probePromises);

  for (const item of settledResults) {
    if (item.status === 'rejected') {
      console.error('[Worker] Unexpected probe rejection:', item.reason);
      continue;
    }

    const { site, result } = item.value;
    const checkTime = new Date().toISOString();
    const newStatus = result.is_up ? 'up' : 'down';
    console.log(
      `[Worker] Probed "${site.name}" (${site.url}) -> ${result.is_up ? 'UP' : 'DOWN'} ` +
      `[HTTP ${result.status_code ?? 'None'}] in ${result.response_ms}ms`
    );

    if (isReal) {
      // STEP 4 — Insert check result
      const { error: checkErr } = await supabase.from('monitor_checks').insert({
        site_id: site.id,
        is_up: result.is_up,
        status_code: result.status_code,
        response_ms: result.response_ms,
        error_message: result.error_message,
        checked_at: checkTime,
      });
      if (checkErr) {
        console.error(`[Worker] Failed to insert check for site ${site.id}:`, checkErr);
      }

      // Fetch previous check to determine state transition
      const { data: prevChecks } = await supabase
        .from('monitor_checks')
        .select('*')
        .eq('site_id', site.id)
        .order('checked_at', { ascending: false })
        .range(1, 1);

      const previousCheck = prevChecks && prevChecks.length > 0 ? prevChecks[0] : null;
      const wasUp = previousCheck ? previousCheck.is_up : site.last_status === 'up';

      // STEP 5 — Update site last_status and last_checked_at
      await supabase
        .from('monitored_sites')
        .update({
          last_status: newStatus,
          last_checked_at: checkTime,
        })
        .eq('id', site.id);

      // STEP 6 — Incident detection (state machine)
      const siteJustWentDown = wasUp && !result.is_up;
      const siteJustCameUp = !wasUp && result.is_up;

      if (siteJustWentDown) {
        console.warn(`[Worker] 🔴 Incident DETECTED: Site "${site.name}" went DOWN`);

        // Create incident
        await supabase.from('incidents').insert({
          site_id: site.id,
          started_at: checkTime,
          root_cause: result.error_message || 'HTTP check failed',
        });

        // STEP 7 — Fetch alert channels and dispatch DOWN notification
        const { data: channels } = await supabase
          .from('alert_channels')
          .select('*')
          .eq('user_id', site.user_id)
          .eq('is_active', true)
          .or(`site_id.eq.${site.id},site_id.is.null`);

        if (channels && channels.length > 0) {
          for (const channel of channels) {
            await sendAlertNotification(channel, {
              site,
              type: 'DOWN',
              timestamp: checkTime,
              errorMessage: result.error_message,
            });
          }
        }
      } else if (siteJustCameUp) {
        console.log(`[Worker] 🟢 Incident RESOLVED: Site "${site.name}" is back UP`);

        // Find open incident
        const { data: openIncidents } = await supabase
          .from('incidents')
          .select('*')
          .eq('site_id', site.id)
          .is('resolved_at', null)
          .order('started_at', { ascending: false })
          .limit(1);

        let durationStr: string | null = null;
        if (openIncidents && openIncidents.length > 0) {
          const openInc = openIncidents[0];
          const durationMs = new Date(checkTime).getTime() - new Date(openInc.started_at).getTime();
          durationStr = formatDuration(durationMs);

          await supabase
            .from('incidents')
            .update({ resolved_at: checkTime })
            .eq('id', openInc.id);
        }

        // STEP 7 — Notification dispatch for UP
        const { data: channels } = await supabase
          .from('alert_channels')
          .select('*')
          .eq('user_id', site.user_id)
          .eq('is_active', true)
          .or(`site_id.eq.${site.id},site_id.is.null`);

        if (channels && channels.length > 0) {
          for (const channel of channels) {
            await sendAlertNotification(channel, {
              site,
              type: 'UP',
              timestamp: checkTime,
              downtimeDuration: durationStr,
            });
          }
        }
      }
    } else {
      // Local fallback demonstration
      console.log(`[Worker] Simulated check recorded: ${site.name} is ${newStatus}`);
    }
  }

  // STEP 8 — Exit cleanly
  console.log('[Worker] Check run completed successfully.');
  process.exit(0);
}

runWorker().catch((err) => {
  console.error('[Worker] Fatal error in worker run:', err);
  process.exit(1);
});
